/* Screens: 03-production-worker, 04-supervisor. Demo data only. */
(function () {
  const { C } = globalThis;
  const R = (s) => globalThis.REG(s);
  const WK = ["PRODUCTION_WORKER", "any role with production.view but without view_all (assigned-only scope)"];
  const SV = ["PRODUCTION_SUPERVISOR", "PRODUCTION_MANAGER", "SUPER_ADMIN (production.approve)"];
  const wNav = (a) => ({ nav: [a, ["Home", "My Work", "Alerts", "Profile"], { Alerts: 1 }] });
  const sNav = (a) => ({ nav: [a, ["Home", "My Work", "Approvals", "Alerts", "Profile"], { Approvals: 4, Alerts: 2 }] });
  const task = (no, stage, lot, done, of, tone, pill) =>
    `<div class="li">${C.tileIcon("layers", tone, 38)}<div class="m"><b>${no} · ${stage}</b><span>${lot}</span><div class="progress" style="margin-top:6px"><i style="width:${Math.round((done / of) * 100)}%"></i></div><span style="margin-top:3px">${done} / ${of} pcs</span></div><div class="r">${C.pill(pill, tone === "muted" ? "neutral" : tone)}</div>${C.icon("chev", "muted", 18)}</div>`;

  // ---------------- 03 PRODUCTION WORKER ----------------
  R({ id: "WRK-001", cat: "03-production-worker", title: "Worker Home", roles: WK, perm: "production.view (assigned scope) + hrms_attendance.view", api: [["GET /api/mobile/v1/me", "N"], ["GET /api/v1/attendance/me/today", "E"], ["GET /api/v1/job-orders/my-assignments", "E"]],
    purpose: "Common employee home plus today's assigned work. Worker sees only own assignments (existing production-scope rules).", actions: ["Tap to Punch", "Open task", "Submit progress"], nav: ["WRK-002", "WRK-003", "EMP-002"],
    render: () => C.frame(`${C.header({ sub: "My Work", unread: 1 })}${C.profile({ dept: "Stitching · Line 3", desig: "Operator" })}<div class="hero" style="padding:14px"><div class="row"><div style="flex:1"><div class="loc"><span>Today's work</span><b style="font-size:22px">3 tasks · 180 pcs left</b><span>${C.icon("checkc", "#43f45d", 14)}Checked in 09:02 AM · Main Factory</span></div></div><div class="ring" style="width:90px;height:90px;border-width:5px"><div><small>Done</small><b>120</b></div></div></div></div>${C.sech("My Tasks", "View all", "layers")}${task("JO-2025-0912", "Stitching", "Lot L-1182 · Polo T-shirt · M", 60, 120, "warning", "In progress")}${task("JO-2025-0915", "Stitching", "Lot L-1185 · Polo T-shirt · L", 0, 80, "info", "Pending")}${C.grid([["Attendance", "calendar", "purple"], ["My Submissions", "clipboard", "primary"], ["Earnings", "rupee", "success"], ["Requests", "file", "warning"]])}`, wNav("Home")) });
  R({ id: "WRK-002", cat: "03-production-worker", title: "My Assigned Work (list)", roles: WK, perm: "production.view; Employee.selfEntryEnabled", api: [["GET /api/v1/job-orders/my-assignments", "E"]],
    purpose: "Own assignments grouped Pending / In progress / Completed (statuses from JobOrderAssignment).", actions: ["Filter tabs", "Search", "Open → WRK-003"], nav: ["WRK-003"],
    render: () => C.frame(`${C.inner("My Assigned Work")}${C.tabs(["Pending 1", "In progress 2", "Completed 14"], 1)}${C.search("Search job order or lot")}${task("JO-2025-0912", "Stitching", "Lot L-1182 · Polo T-shirt · M", 60, 120, "warning", "In progress")}${task("JO-2025-0909", "Stitching", "Lot L-1179 · Kurti · S", 95, 100, "warning", "In progress")}${task("JO-2025-0915", "Stitching", "Lot L-1185 · Polo T-shirt · L", 0, 80, "info", "Pending")}`, wNav("My Work")) });
  R({ id: "WRK-003", cat: "03-production-worker", title: "Task / job order details", roles: WK, perm: "production.view (own assignment rows only)", api: [["GET /api/v1/job-orders/{id}", "E"], ["GET /api/v1/job-orders/{id}/slips", "E"]],
    purpose: "Assigned, done, pending-approval and remaining quantity; stage; lot; slips.", actions: ["Submit progress → WRK-004", "Hand back → WRK-007", "View lot → WRK-008", "Upload slip"], nav: ["WRK-004", "WRK-007", "WRK-008"], h: 900,
    render: () => C.frame(`${C.inner("JO-2025-0912", { sub: "Stitching · Line 3" })}<div class="card"><div class="row"><b style="font-size:16px;flex:1">Polo T-shirt · Navy · M</b>${C.pill("In progress", "warning")}</div><div class="progress" style="margin:10px 0 6px"><i style="width:50%"></i></div><div class="muted">60 of 120 pieces done</div></div>${C.kpis([["Assigned", "120", "pcs"], ["Approved", "50", "pcs", "up"], ["Pending approval", "10", "pcs", "mute"], ["Remaining", "60", "pcs", "mute"]])}${C.kv([["Lot", "L-1182 (view)"], ["Production order", "PO-2025-0331"], ["Assigned on", "02 Nov 2025"], ["Rate", "Shown if allowed by company"]])}${C.btn("Submit progress", "primary", "plus")}${C.btn("Hand back pieces", "secondary", "hand")}`) });
  R({ id: "WRK-004", cat: "03-production-worker", title: "Submit production progress", roles: WK, perm: "production.view + self-entry guards (linked employee, selfEntryEnabled, real assignment, work skill)", api: [["POST /api/v1/job-orders/{id}/self-progress", "E"], ["Voice note on production progress entries (needs a JOB_ORDER_PROGRESS_ENTRY target) — no attachment target yet (CR-001)", "G"]],
    h: 1000, purpose: "Worker logs own quantities (and can record a voice note instead of typing remarks); entry is created PENDING for supervisor approval (existing rule). Capacity check: completed + rejected + damaged − extra ≤ assigned.", actions: ["Submit"], nav: ["WRK-005"],
    validation: ["Whole numbers ≥ 0", "At least one quantity > 0", "Server capacity check (assignment-capacity.ts) with its own message"],
    render: () => C.frame(`${C.inner("Submit Progress", { sub: "JO-2025-0912 · Stitching" })}${C.banner("info", "Remaining: 60 pcs", "Your entry goes to your supervisor for approval.")}<div class="kpis">${["Completed", "Rejected", "Damaged", "Extra"].map((l, i) => `<div class="kpi"><small>${l}</small><b>${[40, 2, 0, 0][i]}</b><i class="mute">− / +</i></div>`).join("")}</div>${C.remark("Remarks", "", "rec", {})}<div class="tile" style="min-height:64px;margin-bottom:12px">${C.tileIcon("camera", "primary", 30)}Attach slip photo (optional)</div>${C.btn("Submit for approval", "primary")}`) });
  R({ id: "WRK-005", cat: "03-production-worker", title: "Submission confirmation", roles: WK, perm: "production.view", api: [["POST /api/v1/job-orders/{id}/self-progress → 201", "E"]],
    purpose: "Confirms the entry is PENDING; no notification is sent on approval today (gap G-11).", actions: ["Done", "View submissions"], nav: ["WRK-006"],
    render: () => C.frame(`<div style="height:90px"></div>${C.state("checkc", "success", "Progress submitted", "42 pieces sent to your supervisor for approval. You can track it in My Submissions.", C.btn("Done", "primary") + C.btn("My submissions", "secondary"))}`) });
  R({ id: "WRK-006", cat: "03-production-worker", title: "My submissions / work history", roles: WK, perm: "production.view", api: [["GET /api/v1/job-order-progress-entries/mine", "E"]],
    purpose: "Own self-entries with approval status and remark.", actions: ["Filter"], nav: [],
    render: () => C.frame(`${C.inner("My Submissions")}${C.tabs(["All", "Pending", "Approved", "Rejected"])}${C.li({ ic: "clipboard", tone: "warning", title: "JO-2025-0912 · 42 pcs", sub: "Today 01:10 PM · Stitching", pill: "Pending", ptone: "warning" })}${C.li({ ic: "clipboard", tone: "success", title: "JO-2025-0912 · 50 pcs", sub: "Yesterday · approved by S. Verma", pill: "Approved", ptone: "success" })}${C.li({ ic: "clipboard", tone: "danger", title: "JO-2025-0909 · 30 pcs", sub: "01 Nov · “Count mismatch, recount”", pill: "Rejected", ptone: "danger" })}`, wNav("My Work")) });
  R({ id: "WRK-007", cat: "03-production-worker", title: "Hand back pieces", roles: WK, perm: "production.view (own assignment)", api: [["POST /api/v1/job-order-assignments/{id}/handback {quantity, reason}", "E"], ["Voice note on hand-back reason — no attachment target yet (CR-001)", "G"]],
    purpose: "Return unworked pieces (lowers assigned qty; logged pieces can't be handed back — server rule).", actions: ["Hand back"], nav: ["WRK-003"], validation: ["Quantity integer > 0 and ≤ unworked", "Reason required"],
    render: () => C.frame(`${C.inner("JO-2025-0912")}${C.kv([["Assigned", "120"], ["Done + pending", "70"]])}`, { overlay: C.sheet(`<b style="font-size:18px">Hand back pieces</b>${C.fld("Quantity", "20", { focus: true, help: "Up to 50 unworked pieces" })}${C.remark("Reason", "", "idle")}${C.btn("Hand back", "danger")}`) }) });
  R({ id: "WRK-008", cat: "03-production-worker", title: "Assigned lot details", roles: WK, perm: "production.view (assertLotInScope)", api: [["GET /api/v1/lots/{id}", "E"]],
    purpose: "Lot facts relevant to the worker (style, colour, size split, current stage).", actions: ["Back"], nav: [],
    render: () => C.frame(`${C.inner("Lot L-1182")}${C.kv([["Style", "Polo T-shirt (ST-102)"], ["Colour", "Navy"], ["Sizes", "S 40 · M 120 · L 80"], ["Current stage", "Stitching"], ["Production order", "PO-2025-0331"]])}${C.banner("info", "You see only your part of this lot", "Other workers' entries are hidden.")}`) });
  R({ id: "WRK-009", cat: "03-production-worker", title: "My piece-rate earnings", roles: WK, perm: "piece_rate.view + ProductionSettings.workersCanViewOwnRate", api: [["GET /api/v1/piece-rate-earnings", "E"]],
    purpose: "Own earnings only, and only if the company allows workers to see rates; otherwise hidden.", actions: ["Filter month"], nav: [],
    render: () => C.frame(`${C.inner("My Earnings", { sub: "November 2025" })}${C.kpis([["This month", "₹ 6,420", "approved", "up", "rupee"], ["Pending", "₹ 380", "awaiting approval", "mute", "clock"]])}${C.li({ ic: "rupee", tone: "success", title: "JO-2025-0912 · 50 pcs", sub: "₹ 4.00 / pc · 03 Nov", right: "₹ 200", chev: false })}${C.li({ ic: "rupee", tone: "success", title: "JO-2025-0909 · 65 pcs", sub: "₹ 5.50 / pc · 01 Nov", right: "₹ 357", chev: false })}`, wNav("My Work")) });
  R({ id: "WRK-010", cat: "03-production-worker", title: "Self-entry not enabled", roles: WK, perm: "—", api: [["GET /api/v1/job-orders/my-assignments → error (not linked / self-entry off)", "E"]],
    purpose: "Clear state when the company has not enabled self entry for this worker (existing Employee.selfEntryEnabled).", actions: ["Contact supervisor"], nav: [],
    render: () => C.frame(`${C.inner("My Assigned Work")}<div style="height:60px"></div>${C.state("lock", "warning", "Self entry is not enabled", "Your supervisor records your work for you. Ask HR or your supervisor to enable self entry if you should log your own work.", "")}`, wNav("My Work")) });

  // ---------------- 04 SUPERVISOR ----------------
  R({ id: "SUP-001", cat: "04-supervisor", title: "Supervisor Home", roles: SV, perm: "production.approve (approvals card); hrms_attendance_team.view (team attendance card, not held by PRODUCTION_SUPERVISOR by default)", api: [["GET /api/mobile/v1/me", "N"], ["GET /api/v1/job-order-progress-entries/pending", "E"], ["GET /api/v1/attendance/summary?date=", "E"], ["Team dashboard counts (team size, active JOs) — server-rendered only", "G"]],
    purpose: "Own attendance + team work + approvals waiting. Cards appear only with permission.", actions: ["Punch", "Approvals → SUP-004", "Team → SUP-002/006"], nav: ["SUP-002", "SUP-004", "SUP-006"],
    render: () => C.frame(`${C.header({ sub: "Supervisor", unread: 2 })}${C.profile({ name: "Suresh Verma", id: "EMP00041", dept: "Stitching", desig: "Line Supervisor", initials: "SV" })}${C.today("08:52 AM")}${C.kpis([["Approvals waiting", "4", "progress entries", "mute", "checkc"], ["Team present", "18 / 22", "today", "up", "users"], ["Active job orders", "11", "team", "mute", "layers"], ["Pieces today", "1,240", "approved", "up", "trend"]])}${C.sech("Waiting for you", "View all")}${C.li({ ic: "clipboard", tone: "warning", title: "Rohit Kumar · 42 pcs", sub: "JO-2025-0912 · Stitching · 1:10 PM", pill: "Pending", ptone: "warning" })}`, sNav("Home")) });
  R({ id: "SUP-002", cat: "04-supervisor", title: "Team attendance today", roles: ["roles with hrms_attendance_team.view (HRMS_TEAM_APPROVER roles, MANAGEMENT)"], perm: "hrms_attendance_team.view", api: [["GET /api/v1/attendance/team-day?date=", "E"]],
    purpose: "Who is in, late, outside, absent today within the HRMS team scope.", actions: ["Filter", "Open member → SUP-003"], nav: ["SUP-003"],
    render: () => C.frame(`${C.inner("Team Attendance", { sub: "Today · 22 members" })}${C.tabs(["All", "In 18", "Late 2", "Outside 1", "Absent 3"])}${C.li({ ic: "user", tone: "success", title: "Rohit Kumar", sub: "In 09:02 · Main Factory", pill: "Present", ptone: "success" })}${C.li({ ic: "user", tone: "warning", title: "Anita Devi", sub: "In 09:51 · late 21 min", pill: "Late", ptone: "warning" })}${C.li({ ic: "user", tone: "warning", title: "Imran Ali", sub: "In 09:10 · 230 m outside", pill: "Review", ptone: "warning" })}${C.li({ ic: "user", tone: "danger", title: "Pooja Singh", sub: "No punch", pill: "Absent", ptone: "danger" })}`, sNav("My Work")) });
  R({ id: "SUP-003", cat: "04-supervisor", title: "Team member details", roles: ["roles with hrms_attendance_records.view"], perm: "hrms_attendance_records.view (team scope)", api: [["GET /api/v1/attendance/team-month?month=&view=team", "E"]],
    purpose: "One member's month summary (existing team-month).", actions: ["Previous month"], nav: [],
    render: () => C.frame(`${C.inner("Anita Devi", { sub: "EMP00077 · Stitching" })}${C.kpis([["Present", "17", "days", "up"], ["Late", "4", "days", "down"], ["Leave", "1", "day"], ["Absent", "0", ""]])}${C.li({ ic: "calendar", tone: "warning", title: "Tue, 04 Nov", sub: "09:51 – running", pill: "Late", ptone: "warning", chev: false })}${C.li({ ic: "calendar", tone: "success", title: "Mon, 03 Nov", sub: "09:28 – 18:40", pill: "Present", ptone: "success", chev: false })}`, sNav("My Work")) });
  R({ id: "SUP-004", cat: "04-supervisor", title: "Pending production approvals", roles: SV, perm: "production.approve (branch + stage + team scope)", api: [["GET /api/v1/job-order-progress-entries/pending", "E"]],
    purpose: "Workers' self entries waiting for approval.", actions: ["Open → SUP-005"], nav: ["SUP-005"],
    render: () => C.frame(`${C.inner("Approvals", { sub: "4 waiting" })}${C.tabs(["Production 4", "Attendance", "Leave"])}${["Rohit Kumar · 42 pcs|JO-2025-0912 · Stitching · 1:10 PM", "Anita Devi · 35 pcs|JO-2025-0909 · Stitching · 12:40 PM", "Imran Ali · 60 pcs|JO-2025-0914 · Stitching · 11:55 AM", "Pooja Singh · 18 pcs|JO-2025-0903 · Finishing · 10:20 AM"].map((s) => { const [t, sub] = s.split("|"); return C.li({ ic: "clipboard", tone: "warning", title: t, sub, pill: "Pending", ptone: "warning" }); }).join("")}${C.banner("info", "Attendance / Leave tabs", "Shown only with HRMS approve permissions.")}`, sNav("Approvals")) });
  R({ id: "SUP-005", cat: "04-supervisor", title: "Approve / reject progress entry", roles: SV, perm: "production.approve (no self-approval)", api: [["POST /api/v1/job-order-progress-entries/{id}/approve {approvalRemark?}", "E"], ["POST /api/v1/job-order-progress-entries/{id}/reject (remark required)", "E"], ["PATCH /api/v1/job-order-progress-entries/{id}", "E"], ["Voice note on progress entries / approval remarks — no attachment target yet (CR-001)", "G"]],
    purpose: "Check the entry against the assignment and approve or reject; server re-checks capacity.", actions: ["Approve", "Reject (remark)", "Edit quantities"], nav: ["SUP-004"], validation: ["Reject needs a remark"],
    render: () => C.frame(`${C.inner("Progress entry")}<div class="card">${C.li({ ic: "user", tone: "primary", title: "Rohit Kumar · EMP00123", sub: "JO-2025-0912 · Stitching · Line 3", chev: false })}${C.kv([["Completed", "40"], ["Rejected", "2"], ["Damaged", "0"], ["Assigned / remaining", "120 / 60"], ["Remark", "—"]])}${C.voice("done", { secs: "0:31" })}</div>${C.remark("Approval remark", "", "idle")}<div class="pair"><div class="btn danger mb0">Reject</div><div class="btn success mb0">Approve</div></div>`) });
  R({ id: "SUP-006", cat: "04-supervisor", title: "Team work status", roles: SV, perm: "production.view (view_all or team)", api: [["GET /api/v1/production-orders (scoped)", "E"], ["Team job-order list / team pending counts", "G"]],
    purpose: "Team's job orders by stage and progress. A team job-order list API does not exist (gap G-05/G-08).", actions: ["Open job order"], nav: [],
    render: () => C.frame(`${C.inner("Team Work", { sub: "Stitching · Line 3" })}${C.banner("warning", "BACKEND_GAP — APPROVAL_REQUIRED", "No team job-order list API today (G-05).")}${task("JO-2025-0912", "Rohit Kumar", "Polo T-shirt · M", 60, 120, "warning", "In progress")}${task("JO-2025-0909", "Anita Devi", "Kurti · S", 95, 100, "warning", "In progress")}${task("JO-2025-0903", "Pooja Singh", "Kurti · M", 100, 100, "success", "Done")}`, sNav("My Work")) });
  R({ id: "SUP-007", cat: "04-supervisor", title: "Team reports", roles: ["roles with reports.view + production.view"], perm: "reports.view + production.view", api: [["GET /api/v1/reports/production/worker-output-register?period=", "E"], ["GET /api/v1/reports/production/line-wise-production", "E"]],
    purpose: "Existing production reports opened in mobile list form.", actions: ["Open report"], nav: ["ADM-006"],
    render: () => C.frame(`${C.inner("Team Reports")}${C.li({ ic: "chart", tone: "primary", title: "Worker output register", sub: "Day / week / month" })}${C.li({ ic: "chart", tone: "primary", title: "Line-wise production" })}${C.li({ ic: "chart", tone: "primary", title: "Production rejection" })}${C.li({ ic: "chart", tone: "primary", title: "Daily attendance", sub: "needs attendance records permission" })}`, sNav("My Work")) });
})();
